let HOLIDAYS = new Set(DEFAULT_HOLIDAYS);
const DOW_JP   = ["日","月","火","水","木","金","土"];
const DOW_FULL = ["日曜日","月曜日","火曜日","水曜日","木曜日","金曜日","土曜日"];

// ─── ユーティリティ ──────────────────────────────────
function parseDate(s) {
  if (!s) return null;
  const parts = s.replace(/\//g,"-").split("-");
  if (parts.length !== 3) return null;
  const [y,m,d] = parts.map(Number);
  if (isNaN(y)||isNaN(m)||isNaN(d)) return null;
  return new Date(y, m-1, d);
}
function fmtDate(d) {
  if (!d) return "";
  return `${d.getFullYear()}/${String(d.getMonth()+1).padStart(2,"0")}/${String(d.getDate()).padStart(2,"0")}`;
}
function toIso(ds) {
  const d = parseDate(ds); if (!d) return "";
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
}
function getYoubi(ds) { const d=parseDate(ds); return d?DOW_FULL[d.getDay()]:""; }
function getKubun(ds, ts) {
  const d = parseDate(ds); if (!d) return {label:"",color:"#546e7a",bg:"#1a2634"};
  const isSun=d.getDay()===0, isHol=HOLIDAYS.has(toIso(ds));
  let isNight=false;
  if (ts) { const h=parseInt(ts.split(":")[0],10); isNight=!isNaN(h)&&(h>=18||h<6); }
  if (isSun&&isNight) return {label:"日曜夜間",color:"#ce93d8",bg:"#1a0a2e"};
  if (isHol&&isNight) return {label:"休日夜間",color:"#ce93d8",bg:"#1a0a2e"};
  if (isSun)          return {label:"日曜",    color:"#ef9a9a",bg:"#2a0a0a"};
  if (isHol)          return {label:"休日",    color:"#ffcc80",bg:"#2a1800"};
  if (isNight)        return {label:"平日夜間",color:"#81d4fa",bg:"#0a1a2a"};
  return                     {label:"平日",    color:"#a5d6a7",bg:"#0a1a0f"};
}
function computeAke(row, allRows) {
  if (!row.startTime || !row.date) return false;
  const h = parseInt(row.startTime.split(":")[0], 10);
  if (isNaN(h) || h < 6 || h >= 12) return false;
  const d = parseDate(row.date);
  if (!d) return false;
  const prev = new Date(d); prev.setDate(prev.getDate() - 1);
  const prevStr = fmtDate(prev);
  return allRows.some(r2 => {
    if (r2.worker !== row.worker || r2.date !== prevStr || !r2.startTime) return false;
    const h2 = parseInt(r2.startTime.split(":")[0], 10);
    return !isNaN(h2) && (h2 >= 18 || h2 < 6);
  });
}

function sortByDate(rows) {
  return [...rows].sort((a,b)=>{
    if (a.date>b.date) return 1;
    if (a.date<b.date) return -1;
    const ta=a.startTime||"", tb=b.startTime||"";
    return ta>tb?1:ta<tb?-1:0;
  });
}

// ─── localStorage ────────────────────────────────────
function lsLoad() {
  try {
    let r=localStorage.getItem(LS_KEY);
    if(!r){for(const k of ['genba_v3','genba_v2','genba_v1']){const o=localStorage.getItem(k);if(o){r=o;break;}}}
    const d = r?JSON.parse(r):{rows:{},sections:DEFAULT_SECTIONS,holidays:DEFAULT_HOLIDAYS};
    if(!d.holidays) d.holidays=DEFAULT_HOLIDAYS;
    HOLIDAYS = new Set(d.holidays);
    // マイグレーション：EDIなし→未実施
    if(d.rows) {
      Object.values(d.rows).forEach(rows=>{
        rows.forEach(row=>{ if(row.billingStatus==="EDIなし") row.billingStatus="未実施"; });
      });
    }
    return d;
  }
  catch { return {rows:{},sections:DEFAULT_SECTIONS,holidays:DEFAULT_HOLIDAYS}; }
}
function lsSave(data) {
  try { localStorage.setItem(LS_KEY,JSON.stringify(data)); } catch {}
  setDoc(doc(firestore,"db","main"), data).catch(console.error);
}

// ─── ANDPAD パーサー ─────────────────────────────────
// ANDPAD側で案件名に付く「【EDI送付済】」「[済]」等の状態タグを除去して現場名を統一する
function normalizeGenbaName(name) {
  return String(name||"").replace(/[【\[][^】\]]*[】\]]/g,"").replace(/\s+/g," ").trim();
}
function parseAndpad(file) {
  return new Promise((res,rej)=>{
    const reader=new FileReader();
    reader.onload=e=>{
      try {
        const wb=XLSX.read(e.target.result,{type:"array"});
        const raw=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,defval:""});
        let drIdx=-1,dateCols={};
        for (let r=0;r<Math.min(10,raw.length);r++) {
          let cnt=0;
          for (let c=4;c<raw[r].length;c++) if(String(raw[r][c]).match(/^\d+\/\d+$/))cnt++;
          if(cnt>=5){drIdx=r;for(let c=4;c<raw[r].length;c++){const v=String(raw[r][c]).trim();if(v.match(/^\d+\/\d+$/))dateCols[c]=v;}break;}
        }
        if(drIdx===-1){rej("日付行が見つかりません");return;}
        let year=new Date().getFullYear();
        for(let r=0;r<5;r++)for(let c=0;c<raw[r].length;c++){const m=String(raw[r][c]).match(/(\d{4})\/\d{2}\/\d{2}/);if(m){year=parseInt(m[1]);break;}}
        const result={};
        let i=drIdx+2;
        let currentWorker=null;
        while(i<raw.length){
          const row=raw[i];
          const pn=String(row[2]||"").trim().replace(/\s/g,"");
          const matched=WORKERS.find(w=>w.replace(/\s/g,"")===pn);
          if(matched) currentWorker=matched;
          // 「案件名」ラベルが来たらそのスロット（8行）を処理
          if(currentWorker && String(row[4]||"").trim()==="案件名"){
            const block={};
            for(let j=i;j<Math.min(i+8,raw.length);j++){const lbl=String(raw[j][4]||"").trim();if(lbl)block[lbl]=j;}
            if(!result[currentWorker])result[currentWorker]=[];
            for(const [ci_s,ds] of Object.entries(dateCols)){
              const ci=parseInt(ci_s);
              const gv=lbl=>{if(block[lbl]===undefined)return "";const v=raw[block[lbl]][ci];return String(v||"").trim();};
              const genba=normalizeGenbaName(gv("案件名")),jikan=gv("時間"),eigyo=gv("営業担当"),soka=gv("所課");
              if(!genba||genba==="nan")continue;
              let st="";
              if(jikan&&jikan!=="時刻未定"){const m=jikan.split("-")[0].trim().match(/^(\d+):(\d+)/);if(m){let h=parseInt(m[1]);if(h>=24)h-=24;st=`${String(h).padStart(2,"0")}:${m[2]}`;}}
              const d=parseDate(`${year}/${ds}`);
              const eigyoVal=eigyo!=="nan"?eigyo:"";
              const sokaVal=soka!=="nan"?soka:"";
              result[currentWorker].push({
                id:Math.random().toString(36).slice(2),
                date:d?fmtDate(d):`${year}/${ds}`, youbi:d?getYoubi(fmtDate(d)):"",
                startTime:st, genba,
                subjects:[],inspectionTypes:[],sections:[],eigyoList:[],
                eigyo:eigyoVal, _importSoka:sokaVal,
                yotei:"",memo:"",reportStatus:"未実施",photoBookStatus:"未実施",expressGo:false,expressReturn:false,expressMid:false,
                edi:"",hoteifukuri:"",futan:"",futan2:"",ake:false,
                billingStatus:"未実施",worker:currentWorker,
                assignedBy:"admin",assignedAt:Date.now(),
              });
            }
          }
          i++;
        }
        res(result);
      }catch(err){rej(err);}
    };
    reader.readAsArrayBuffer(file);
  });
}

