// ─── ドラッグ&ドロップ カードリスト（PC） ───────────
function DraggableList({rows, renderCard, onReorder}) {
  const dragId = useRef(null);
  const [dragOverId, setDragOverId] = useState(null);

  const doReorder = (fromId, toId) => {
    if (!fromId||!toId||fromId===toId) return;
    const fromRow=rows.find(r=>r.id===fromId);
    const toRow=rows.find(r=>r.id===toId);
    if (!fromRow||!toRow) return;
    if (fromRow.date!==toRow.date) {
      alert(`同じ日付の現場のみ並び替えできます。\n（${fromRow.date} → ${toRow.date} への移動はできません）`);
      return;
    }
    const n=[...rows];
    const fi=n.findIndex(r=>r.id===fromId);
    const ti=n.findIndex(r=>r.id===toId);
    const [m]=n.splice(fi,1); n.splice(ti,0,m);
    onReorder(n);
  };

  return (
    <div style={{display:"flex",flexDirection:"column",gap:8}}>
      {rows.map(row=>(
        <div key={row.id} data-row-id={row.id}
          draggable
          onDragStart={e=>{ dragId.current=row.id; e.dataTransfer.effectAllowed="move"; }}
          onDragOver={e=>{ e.preventDefault(); setDragOverId(row.id); }}
          onDrop={e=>{ e.preventDefault(); setDragOverId(null); doReorder(dragId.current,row.id); dragId.current=null; }}
          onDragEnd={()=>{ setDragOverId(null); dragId.current=null; }}
          style={{opacity:dragId.current===row.id?0.4:1,outline:dragOverId===row.id?"2px dashed #4fc3f7":"none",borderRadius:10,cursor:"grab"}}>
          {renderCard(row)}
        </div>
      ))}
    </div>
  );
}// ─── 定期点検フォーム ────────────────────────────────
