async function compressImage(file) {
  return new Promise(resolve => {
    const img = new Image();
    const url = URL.createObjectURL(file);
    img.onload = () => {
      const MAX = 1200;
      let w = img.width, h = img.height;
      if (w > MAX) { h = Math.round(h * MAX / w); w = MAX; }
      const canvas = document.createElement("canvas");
      canvas.width = w; canvas.height = h;
      canvas.getContext("2d").drawImage(img, 0, 0, w, h);
      canvas.toBlob(blob => { URL.revokeObjectURL(url); resolve(blob); }, "image/jpeg", 0.75);
    };
    img.src = url;
  });
}

function InfoShareView({ db, setDb, isAdmin, userName }) {
  const folders = db.infoFolders || [];
  const posts = db.infoPosts || [];
  const [currentId, setCurrentId] = useState(null);
  const [newFolderName, setNewFolderName] = useState("");
  const [newPostText, setNewPostText] = useState("");
  const [pendingFile, setPendingFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [showNewFolder, setShowNewFolder] = useState(false);
  const [movingFolder, setMovingFolder] = useState(null);
  const [renamingFolder, setRenamingFolder] = useState(null);
  const [renameInput, setRenameInput] = useState("");
  const [toolView, setToolView] = useState(null);
  const fileInputRef = useRef(null);

  const saveInfo = (update) => {
    const nd = { ...db, ...update };
    setDb(nd); lsSave(nd);
  };

  const currentFolder = folders.find(f => f.id === currentId) || null;
  const childFolders = folders.filter(f => f.parentId === currentId);
  const currentPosts = posts.filter(p => p.folderId === currentId);
  const canPost = isAdmin || (currentFolder?.canWorkerPost);

  // パンくずリスト
  const getBreadcrumb = (id) => {
    const path = [];
    let cur = id;
    while (cur) {
      const f = folders.find(x => x.id === cur);
      if (!f) break;
      path.unshift(f);
      cur = f.parentId;
    }
    return path;
  };
  const breadcrumb = getBreadcrumb(currentId);

  const addFolder = () => {
    const name = newFolderName.trim();
    if (!name) return;
    const newFolder = { id: Date.now().toString(), name, parentId: currentId, canWorkerPost: false };
    saveInfo({ infoFolders: [...folders, newFolder] });
    setNewFolderName(""); setShowNewFolder(false);
  };

  const deleteFolder = (id) => {
    if (!window.confirm("このフォルダを削除しますか？（中のファイルも削除されます）")) return;
    const allIds = [id];
    const collect = (pid) => { folders.filter(f => f.parentId === pid).forEach(f => { allIds.push(f.id); collect(f.id); }); };
    collect(id);
    saveInfo({
      infoFolders: folders.filter(f => !allIds.includes(f.id)),
      infoPosts: posts.filter(p => !allIds.includes(p.folderId))
    });
  };

  const toggleWorkerPost = (id) => {
    saveInfo({ infoFolders: folders.map(f => f.id === id ? { ...f, canWorkerPost: !f.canWorkerPost } : f) });
  };

  const renameFolder = () => {
    const name = renameInput.trim();
    if (!name || !renamingFolder) return;
    saveInfo({ infoFolders: folders.map(f => f.id === renamingFolder.id ? { ...f, name } : f) });
    setRenamingFolder(null); setRenameInput("");
  };

  const moveFolderOrder = (id, dir) => {
    const siblings = folders.filter(f => f.parentId === currentId);
    const idx = siblings.findIndex(f => f.id === id);
    const newIdx = idx + dir;
    if (newIdx < 0 || newIdx >= siblings.length) return;
    const newSiblings = [...siblings];
    [newSiblings[idx], newSiblings[newIdx]] = [newSiblings[newIdx], newSiblings[idx]];
    const otherFolders = folders.filter(f => f.parentId !== currentId);
    saveInfo({ infoFolders: [...otherFolders, ...newSiblings] });
  };

  const moveFolder = (destId) => {
    if (!movingFolder) return;
    // 移動先が自分自身または子孫の場合は禁止
    const isDescendant = (targetId, ancestorId) => {
      let cur = targetId;
      while (cur) {
        if (cur === ancestorId) return true;
        cur = folders.find(f => f.id === cur)?.parentId || null;
      }
      return false;
    };
    if (destId === movingFolder.id || isDescendant(destId, movingFolder.id)) return;
    saveInfo({ infoFolders: folders.map(f => f.id === movingFolder.id ? { ...f, parentId: destId } : f) });
    setMovingFolder(null);
  };

  // 移動先として選べるフォルダ一覧（自分自身と子孫を除く）
  const getMoveTargets = (folderId) => {
    const isDescendant = (targetId) => {
      let cur = targetId;
      while (cur) {
        if (cur === folderId) return true;
        cur = folders.find(f => f.id === cur)?.parentId || null;
      }
      return false;
    };
    return folders.filter(f => f.id !== folderId && !isDescendant(f.id));
  };

  const submitPost = async () => {
    if (!newPostText.trim() && !pendingFile) return;
    setUploading(true);
    try {
      let fileData = {};
      if (pendingFile) {
        const isImage = pendingFile.type.startsWith("image/");
        const blob = isImage ? await compressImage(pendingFile) : pendingFile;
        const path = `info/${Date.now()}_${pendingFile.name}`;
        const storageRef = ref(storage, path);
        await uploadBytes(storageRef, blob);
        const url = await getDownloadURL(storageRef);
        fileData = { type: isImage ? "image" : "file", fileName: pendingFile.name, fileUrl: url, storagePath: path };
      }
      const p = { id: Date.now().toString(), folderId: currentId, postedBy: userName, postedAt: new Date().toISOString(), ...(newPostText.trim() ? {content: newPostText.trim()} : {}), ...fileData };
      saveInfo({ infoPosts: [...posts, p] });
      setNewPostText(""); setPendingFile(null);
    } catch { alert("アップロードに失敗しました"); }
    setUploading(false);
  };

  const deletePost = async (post) => {
    if (!window.confirm("削除しますか？")) return;
    if (post.storagePath) { try { await deleteObject(ref(storage, post.storagePath)); } catch {} }
    saveInfo({ infoPosts: posts.filter(p => p.id !== post.id) });
  };

  return (
    <div style={{ padding: 16 }}>
      {/* 技術資料 iframeオーバーレイ */}
      {toolView && (
        <div style={{position:"fixed",inset:0,background:"#080e14",zIndex:200,display:"flex",flexDirection:"column"}}>
          <div style={{padding:"8px 14px",background:"#0d1520",borderBottom:"1px solid #1a2634",display:"flex",alignItems:"center",gap:10,flexShrink:0}}>
            <button onClick={()=>setToolView(null)} style={{...btnBase,background:"transparent",color:"#4fc3f7",border:"1px solid #1e4a5a",fontSize:12}}>← 戻る</button>
            <span style={{color:"#cfd8dc",fontSize:13,fontWeight:700}}>{toolView==='manual'?'📘 業務マニュアル':'📋 OSD一式交換調査票'}</span>
          </div>
          <iframe
            src={import.meta.env.BASE_URL + (toolView==='manual'?'shutter-manual.html':'osd-chosahyo.html')}
            style={{flex:1,border:"none",display:"block"}}
            title={toolView==='manual'?'業務マニュアル':'OSD一式交換調査票'}
          />
        </div>
      )}

      {/* パンくず */}
      <div style={{ display: "flex", gap: 4, alignItems: "center", marginBottom: 14, flexWrap: "wrap" }}>
        <span onClick={() => setCurrentId(null)} style={{ color: "#4fc3f7", cursor: "pointer", fontSize: 13, fontWeight: 700 }}>📁 情報共有</span>
        {breadcrumb.map(f => (
          <span key={f.id} style={{ display: "flex", alignItems: "center", gap: 4 }}>
            <span style={{ color: "#546e7a" }}>›</span>
            <span onClick={() => setCurrentId(f.id)} style={{ color: "#4fc3f7", cursor: "pointer", fontSize: 13, fontWeight: 700 }}>{f.name}</span>
          </span>
        ))}
      </div>

      {/* 技術資料セクション（ルートレベル） */}
      {currentId === null && (
        <div style={{marginBottom:16,padding:"10px 14px",background:"#0d1520",border:"1px solid #1a2634",borderRadius:8}}>
          <div style={{color:"#78909c",fontSize:11,fontWeight:700,marginBottom:8,letterSpacing:1}}>📚 技術資料</div>
          <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
            <button onClick={()=>setToolView('manual')}
              style={{...btnBase,background:"#0d2030",color:"#4fc3f7",border:"1px solid #1e4a5a",fontSize:12}}>
              📘 業務マニュアル
            </button>
            <button onClick={()=>setToolView('osd')}
              style={{...btnBase,background:"#1a1400",color:"#ffd54f",border:"1px solid #2a2000",fontSize:12}}>
              📋 OSD調査票
            </button>
          </div>
        </div>
      )}

      {/* フォルダ一覧 */}
      {childFolders.length > 0 && (
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 14 }}>
          {childFolders.map(f => (
            <div key={f.id} style={{ background: "#0d1520", border: "1px solid #1a2634", borderRadius: 8, padding: "10px 14px", cursor: "pointer", minWidth: 120, position: "relative" }}
              onClick={() => setCurrentId(f.id)}>
              <div style={{ fontSize: 20, marginBottom: 4 }}>📁</div>
              <div style={{ color: "#cfd8dc", fontSize: 12, fontWeight: 700 }}>{f.name}</div>
              {f.canWorkerPost && <div style={{ color: "#a5d6a7", fontSize: 9, marginTop: 2 }}>✏️ 全員投稿可</div>}
              {isAdmin && (
                <div style={{ display: "flex", gap: 4, marginTop: 6 }} onClick={e => e.stopPropagation()}>
                  <button onClick={() => toggleWorkerPost(f.id)}
                    style={{ fontSize: 9, padding: "2px 6px", borderRadius: 4, border: "1px solid #1a2634", background: f.canWorkerPost ? "#0a1f0a" : "transparent", color: f.canWorkerPost ? "#a5d6a7" : "#546e7a", cursor: "pointer", fontFamily: "inherit" }}>
                    {f.canWorkerPost ? "全員投稿可" : "管理者のみ"}
                  </button>
                  <button onClick={()=>moveFolderOrder(f.id,-1)}
                    style={{fontSize:11,padding:"2px 6px",borderRadius:4,border:"1px solid #1a2634",background:"transparent",color:"#546e7a",cursor:"pointer",fontFamily:"inherit"}}>↑</button>
                  <button onClick={()=>moveFolderOrder(f.id,1)}
                    style={{fontSize:11,padding:"2px 6px",borderRadius:4,border:"1px solid #1a2634",background:"transparent",color:"#546e7a",cursor:"pointer",fontFamily:"inherit"}}>↓</button>
                  <button onClick={() => { setRenamingFolder(f); setRenameInput(f.name); }}
                    style={{ fontSize: 9, padding: "2px 6px", borderRadius: 4, border: "1px solid #1a2634", background: "transparent", color: "#4fc3f7", cursor: "pointer", fontFamily: "inherit" }}>名前変更</button>
                  <button onClick={() => setMovingFolder(f)}
                    style={{ fontSize: 9, padding: "2px 6px", borderRadius: 4, border: "1px solid #1a2634", background: "transparent", color: "#ffd54f", cursor: "pointer", fontFamily: "inherit" }}>移動</button>
                  <button onClick={() => deleteFolder(f.id)}
                    style={{ fontSize: 9, padding: "2px 6px", borderRadius: 4, border: "1px solid #1a2634", background: "transparent", color: "#ef5350", cursor: "pointer", fontFamily: "inherit" }}>削除</button>
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {/* 投稿一覧 */}
      <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 14 }}>
        {currentPosts.length === 0 && childFolders.length === 0 && (
          <div style={{ color: "#1a2634", fontSize: 12, textAlign: "center", padding: 24 }}>まだ何もありません</div>
        )}
        {currentPosts.map(p => (
          <div key={p.id} style={{ background: "#0d1520", border: "1px solid #1a2634", borderRadius: 8, padding: "10px 14px" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
              <div style={{ flex: 1 }}>
                {p.content && <div style={{ color: "#cfd8dc", fontSize: 13, whiteSpace: "pre-wrap", lineHeight: 1.6 }}>{p.content}</div>}
                {p.fileUrl && p.type === "image" && (
                  <button onClick={() => window.open(p.fileUrl, "_blank")}
                    style={{ display: "inline-flex", alignItems: "center", gap: 6, marginTop: p.content ? 6 : 0, padding: "5px 12px", borderRadius: 6, border: "1px solid #1e4a5a", background: "#0d2030", color: "#4fc3f7", fontSize: 12, cursor: "pointer", fontFamily: "inherit" }}>
                    📷 画像あり
                  </button>
                )}
                {p.fileUrl && p.type === "file" && (
                  <a href={p.fileUrl} target="_blank" rel="noreferrer"
                    style={{ display: "inline-flex", alignItems: "center", gap: 6, marginTop: p.content ? 6 : 0, padding: "5px 12px", borderRadius: 6, border: "1px solid #1a2634", background: "#0a1018", color: "#4fc3f7", fontSize: 12 }}>
                    📎 {p.fileName}
                  </a>
                )}
                <div style={{ color: "#37474f", fontSize: 10, marginTop: 6 }}>{p.postedBy} · {p.postedAt?.slice(0, 10)}</div>
              </div>
              {(isAdmin || p.postedBy === userName) && (
                <button onClick={() => deletePost(p)} style={{ ...btnBase, background: "transparent", color: "#ef5350", border: "none", fontSize: 11, padding: "2px 6px", flexShrink: 0 }}>✕</button>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* 投稿フォーム */}
      {(currentId !== null) && canPost && (
        <div style={{ background: "#0a1018", border: "1px solid #1a2634", borderRadius: 8, padding: 12, marginBottom: 14 }}>
          <textarea value={newPostText} onChange={e => setNewPostText(e.target.value)}
            placeholder="テキストを入力（任意）..." rows={3}
            style={{ width: "100%", background: "#080e14", border: "1px solid #1a2634", borderRadius: 6, padding: "8px 10px", color: "#cfd8dc", fontSize: 13, fontFamily: "inherit", resize: "vertical", marginBottom: 8 }} />
          {pendingFile && (
            <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 8, padding: "5px 10px", background: "#080e14", borderRadius: 5, border: "1px solid #1a2634" }}>
              <span style={{ color: "#a5d6a7", fontSize: 11 }}>{pendingFile.type.startsWith("image/") ? "📷" : "📎"} {pendingFile.name}</span>
              <button onClick={() => setPendingFile(null)} style={{ color: "#ef5350", background: "none", border: "none", cursor: "pointer", fontSize: 12, marginLeft: "auto" }}>✕</button>
            </div>
          )}
          <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
            <button onClick={submitPost} disabled={uploading || (!newPostText.trim() && !pendingFile)}
              style={{ ...btnBase, background: (newPostText.trim()||pendingFile)?"#0d2030":"#0a1018", color: (newPostText.trim()||pendingFile)?"#4fc3f7":"#1a2634", border: "1px solid #1e4a5a", fontSize: 12 }}>
              {uploading ? "送信中..." : "投稿"}
            </button>
            <button onClick={() => fileInputRef.current?.click()} disabled={uploading}
              style={{ ...btnBase, background: pendingFile?"#0a1f0a":"transparent", color: "#a5d6a7", border: "1px solid #1a3a1a", fontSize: 12 }}>
              📎 {pendingFile ? "変更" : "ファイル・画像"}
            </button>
            <input ref={fileInputRef} type="file" accept="image/*,.pdf,.doc,.docx,.xls,.xlsx" style={{ display: "none" }}
              onChange={e => { if (e.target.files[0]) setPendingFile(e.target.files[0]); e.target.value = ""; }} />
          </div>
        </div>
      )}

      {/* 名前変更モーダル */}
      {renamingFolder && (
        <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.7)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:1000}}>
          <div style={{background:"#0d1520",border:"1px solid #1a2634",borderRadius:12,padding:20,width:300}}>
            <div style={{color:"#4fc3f7",fontWeight:700,fontSize:13,marginBottom:12}}>フォルダ名を変更</div>
            <input value={renameInput} onChange={e=>setRenameInput(e.target.value)}
              onKeyDown={e=>e.key==="Enter"&&renameFolder()}
              style={{...mi,width:"100%",marginBottom:12}} autoFocus/>
            <div style={{display:"flex",gap:8}}>
              <button onClick={renameFolder} style={{...btnBase,background:"#0d2030",color:"#4fc3f7",border:"1px solid #1e4a5a",fontSize:12,flex:1}}>変更</button>
              <button onClick={()=>setRenamingFolder(null)} style={{...btnBase,background:"transparent",color:"#546e7a",border:"1px solid #1a2634",fontSize:12,flex:1}}>キャンセル</button>
            </div>
          </div>
        </div>
      )}

      {/* 移動先選択モーダル */}
      {movingFolder && (
        <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.7)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:1000}}>
          <div style={{background:"#0d1520",border:"1px solid #1a2634",borderRadius:12,padding:20,width:320,maxHeight:"70vh",overflowY:"auto"}}>
            <div style={{color:"#ffd54f",fontWeight:700,fontSize:13,marginBottom:12}}>「{movingFolder.name}」の移動先</div>
            <div style={{display:"flex",flexDirection:"column",gap:6}}>
              <button onClick={()=>moveFolder(null)}
                style={{...btnBase,background:"#080e14",color:"#4fc3f7",border:"1px solid #1a2634",fontSize:12,textAlign:"left",padding:"8px 12px"}}>
                📂 ホーム（最上位）
              </button>
              {getMoveTargets(movingFolder.id).map(f=>(
                <button key={f.id} onClick={()=>moveFolder(f.id)}
                  style={{...btnBase,background:"#080e14",color:"#cfd8dc",border:"1px solid #1a2634",fontSize:12,textAlign:"left",padding:"8px 12px"}}>
                  📁 {f.name}
                </button>
              ))}
            </div>
            <button onClick={()=>setMovingFolder(null)} style={{...btnBase,marginTop:12,background:"transparent",color:"#546e7a",border:"1px solid #1a2634",fontSize:12,width:"100%"}}>キャンセル</button>
          </div>
        </div>
      )}

      {/* フォルダ追加（管理者のみ） */}
      {isAdmin && (
        <div>
          {showNewFolder ? (
            <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
              <input value={newFolderName} onChange={e => setNewFolderName(e.target.value)}
                onKeyDown={e => e.key === "Enter" && addFolder()}
                placeholder="フォルダ名" style={{ ...mi, flex: 1 }} autoFocus />
              <button onClick={addFolder} style={{ ...btnBase, background: "#0d2030", color: "#4fc3f7", border: "1px solid #1e4a5a", fontSize: 12 }}>作成</button>
              <button onClick={() => setShowNewFolder(false)} style={{ ...btnBase, background: "transparent", color: "#546e7a", border: "1px solid #1a2634", fontSize: 12 }}>キャンセル</button>
            </div>
          ) : (
            <button onClick={() => setShowNewFolder(true)} style={{ ...btnBase, background: "transparent", border: "1px solid #1a2634", color: "#546e7a", fontSize: 12 }}>
              📁 フォルダを追加
            </button>
          )}
        </div>
      )}
    </div>
  );
}

// ═══════════════════════════════════════════════════════
// ROOT
// ═══════════════════════════════════════════════════════
export default function App() {
  const [db, setDb] = useState(()=>lsLoad());
  const [session, setSession] = useState(()=>{try{const s=sessionStorage.getItem("session");return s?JSON.parse(s):null;}catch{return null;}});
  const [synced, setSynced] = useState(false);
  const [gateOk, setGateOk] = useState(()=>sessionStorage.getItem("gateOk")==="1");
  const dbRef = useRef(db);
  useEffect(()=>{ dbRef.current = db; },[db]);

  useEffect(()=>{
    const unsub = onSnapshot(doc(firestore,"db","main"), snap=>{
      if(snap.exists()){
        const data = snap.data();
        if(!data.holidays) data.holidays = DEFAULT_HOLIDAYS;
        HOLIDAYS = new Set(data.holidays);
        setDb(data);
        try { localStorage.setItem(LS_KEY,JSON.stringify(data)); } catch {}
      }
      setSynced(true);
    }, ()=>setSynced(true));
    return unsub;
  },[]);

  useEffect(()=>{
    const handler = (e) => {
      if(!e.data) return;
      if(e.data.type==='osd_save'){
        setDb(prev=>{const nd={...prev,osdFormData:e.data.d};lsSave(nd);return nd;});
      }
      if(e.data.type==='osd_ready'){
        const iframe = document.querySelector('iframe[title="OSD一式交換調査票"]');
        if(iframe && dbRef.current.osdFormData){
          iframe.contentWindow.postMessage({type:'osd_init',d:dbRef.current.osdFormData},'*');
        }
      }
    };
    window.addEventListener('message',handler);
    return ()=>window.removeEventListener('message',handler);
  },[]);

  if(!synced) return (
    <div style={{minHeight:"100vh",background:"#080e14",display:"flex",alignItems:"center",justifyContent:"center",color:"#4fc3f7",fontFamily:"'Noto Sans JP',sans-serif",fontSize:14}}>
      読み込み中…
    </div>
  );

  if(!gateOk) return <GateLogin onPass={()=>{sessionStorage.setItem("gateOk","1");setGateOk(true);}}/>;

  return !session
    ? <Login db={db} onLogin={s=>{sessionStorage.setItem("session",JSON.stringify(s));setSession(s);}} onSave={nd=>{setDb(nd);lsSave(nd);}} extraCoworkers={db.extraCoworkers||[]}/>
    : session.role==="admin"
      ? <AdminView db={db} setDb={setDb} onLogout={()=>{sessionStorage.removeItem("session");setSession(null);}}/>
      : <WorkerView user={session} db={db} setDb={setDb} onLogout={()=>{sessionStorage.removeItem("session");setSession(null);}}/>;
}

const btnBase={padding:"8px 14px",borderRadius:7,border:"none",fontSize:12,fontWeight:600,cursor:"pointer",fontFamily:"inherit"};
const mi={background:"#0a1018",border:"1px solid #1a2634",borderRadius:5,padding:"6px 8px",fontSize:12,color:"#cfd8dc",outline:"none",fontFamily:"inherit"};
const selA={padding:"5px 8px",borderRadius:6,border:"1px solid #1a2634",background:"#080e14",color:"#546e7a",fontSize:11,fontFamily:"inherit",cursor:"pointer"};
const sinp={background:"#0d1520",border:"1px solid #1a2634",borderRadius:5,padding:"5px 8px",fontSize:11,color:"#78909c",outline:"none",fontFamily:"inherit"};
